// PokePoke opencode integration — auto-generated by `poke-hook --install-opencode`.
// pokepoke-plugin-marker
// Do not edit by hand; re-run Connect from the PokePoke tray to regenerate.
//
// Forwards opencode session lifecycle events to the local PokePoke app via the
// poke-hook binary. Failures are swallowed so a notification hiccup never
// disrupts your opencode session. Uses child_process.spawn so it works under
// both Node (opencode 1.14.37+ sidecar) and Bun (older CLI) runtimes.
import { createRequire } from "module"
const require = createRequire(import.meta.url)

const POKE_HOOK = "__POKE_HOOK_BIN__"

// Track forwarded user message IDs to avoid re-forwarding the same message
// when opencode fires `message.updated` again after a session completes.
// Without this, a `session.idle` → Idle popup is immediately replaced by the
// re-fire → Running, and the popup is never seen.
const seenMessages = new Set()
// Track session.created to avoid duplicate SessionStart events. opencode may
// fire session.created more than once for the same session, and each
// SessionStart triggers a Ghostty terminal_id capture. The second capture
// races and may grab the wrong tab (the frontmost Ghostty window at that
// instant, which could be a different session).
const seenSessions = new Set()
// Sessions that already errored this round. When `session.error` fires we
// immediately forward StopFailure (failure sound). If the same round later
// emits `session.idle`, its debounced Stop must NOT fire -- otherwise the
// user hears the failure sound, then a "completed" sound 10s later for the
// same failed round. Cleared when a new round starts (session.created / new
// user message) so later normal completions still play their sound.
const erroredSessions = new Set()
// opencode fires `session.idle` after EVERY tool-call iteration, not just
// when the agent genuinely waits for user input. We debounce idle events:
// wait 10 seconds before forwarding. If a new user message arrives within
// that window, the idle was just an iteration gap — cancel the Stop.
// See memory: project-20260708-opencode-idle-iteration-gap
const idleTimers = new Map()

// Soft cap on dedup sets so a long-lived opencode process (many sessions /
// messages accumulated over days) doesn't grow unbounded memory. Dedup here
// is best-effort -- the server side also dedupes -- so clearing on overflow
// only risks a rare re-forward, not a correctness bug. idleTimers self-cleans
// (delete on fire / cancel) so it doesn't need capping.
const DEDUP_CAP = 2000
function remember(set, id) {
  if (set.size >= DEDUP_CAP) set.clear()
  set.add(id)
}

function forward(payload) {
  try {
    const { spawn } = require("child_process")
    const child = spawn(POKE_HOOK, ["--source=opencode"], {
      stdio: ["pipe", "ignore", "ignore"],
    })
    child.on("error", () => {})
    child.stdin.on("error", () => {})
    child.stdin.write(JSON.stringify(payload))
    child.stdin.end()
  } catch {
    // never let a notification failure surface into opencode
  }
}

export default async ({ directory }) => {
  return {
    event: async ({ event }) => {
      const p = (event && event.properties) || {}
      switch (event && event.type) {
        case "session.created":
          if (p.info && p.info.id && !seenSessions.has(p.info.id)) {
            remember(seenSessions, p.info.id)
            // A brand-new session starts clean: forget any errored marker so
            // its future completions still play the completion sound.
            erroredSessions.delete(p.info.id)
            forward({
              hook_event_name: "SessionStart",
              session_id: p.info.id,
              cwd: (p.info && p.info.directory) || directory,
            })
          }
          break
        case "message.updated":
          // Only user messages mean "a new turn started". Assistant messages
          // update on every streamed part and would spam Running otherwise.
          // Dedupe by message id: opencode re-fires message.updated for the
          // same user message (e.g. after completion), which would otherwise
          // flip a fresh Idle popup back to Running and hide it.
          if (p.info && p.info.role === "user" && p.info.id && !seenMessages.has(p.info.id)) {
            remember(seenMessages, p.info.id)
            // Cancel any pending idle debounce: a new user message means
            // the agent is still working, not genuinely waiting for input.
            const mid = p.info.sessionID
            if (idleTimers.has(mid)) {
              clearTimeout(idleTimers.get(mid))
              idleTimers.delete(mid)
            }
            // A new user message starts a new round: the previous round's
            // error must not silence this round's completion sound.
            erroredSessions.delete(mid)
            forward({
              hook_event_name: "UserPromptSubmit",
              session_id: p.info.sessionID,
              cwd: directory,
            })
          }
          break
        case "session.idle":
          // Debounce: wait 10s before forwarding Stop. If a new user message
          // arrives within this window, the idle was just an iteration gap.
          const sid = p.sessionID
          if (idleTimers.has(sid)) {
            clearTimeout(idleTimers.get(sid))
          }
          idleTimers.set(sid, setTimeout(() => {
            idleTimers.delete(sid)
            // This round already errored: StopFailure (failure sound) was
            // forwarded when `session.error` fired. Sending Stop now would
            // add a misleading "completed" sound for a failed round.
            if (erroredSessions.has(sid)) {
              erroredSessions.delete(sid)
              return
            }
            forward({
              hook_event_name: "Stop",
              session_id: sid,
              cwd: directory,
            })
          }, 10000))
          break
        case "permission.updated":
          // properties IS the Permission object (sessionID + title).
          // Cancel any pending idle debounce: a permission prompt means the
          // agent is actively waiting for user approval, not idle. Without
          // this, a session.idle fired ~10s ago would still emit Stop and
          // clobber this Pending status (server upsert has no
          // Pending-over-Idle priority protection).
          if (idleTimers.has(p.sessionID)) {
            clearTimeout(idleTimers.get(p.sessionID))
            idleTimers.delete(p.sessionID)
          }
          forward({
            hook_event_name: "Notification",
            session_id: p.sessionID,
            cwd: directory,
            message: p.title ? `Awaiting approval: ${p.title}` : "Awaiting approval",
          })
          break
        case "session.error":
          remember(erroredSessions, p.sessionID)
          // A pending idle debounce is meaningless once the round errored:
          // drop it now instead of letting it fire a Stop later.
          if (idleTimers.has(p.sessionID)) {
            clearTimeout(idleTimers.get(p.sessionID))
            idleTimers.delete(p.sessionID)
          }
          forward({
            hook_event_name: "StopFailure",
            session_id: p.sessionID,
            cwd: directory,
            reason: (p.error && (p.error.name || p.error.type)) || "unknown",
          })
          break
      }
    },
  }
}
